style.css:
@-moz-document domain("roblox.com") {
body {
    background-image: url("http://images4.fanpop.com/image/photos/22500000/Mikami-Teru-mikami-22519174-1024-768.jpg");
    background-size: cover;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-position: center;
  }

  .theme-base,
  .content,
  .container,
  .page-content,
  .section-content {
    background: rgba(0, 0, 0, 0.4) !important;
    color: #fff !important;
  }

  .navbar,
  .footer-container {
    background: rgba(0, 0, 0, 0.7) !important;
  }
}
